#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define NUM_THREADS 2

/* Common data structure for threads */
struct thread_data {
    struct k_thread thread;
    k_tid_t tid;
    int executed_count;
    int id;
    bool should_run;
};

K_THREAD_STACK_ARRAY_DEFINE(test_stacks, NUM_THREADS, STACK_SIZE);
struct thread_data test_tdata[NUM_THREADS];

/* Test for k_sleep with cooperative threads */
void cooperative_sleep_thread_entry(void *p1, void *p2, void *p3) {
    struct thread_data *data = (struct thread_data *)p1;
    data->executed_count++; /* Increment once */
    k_sleep(K_MSEC(100)); /* Sleep for a duration */
    /* The thread will become runnable after 100ms, but the test checks before it runs again. */
}

/* Test for k_yield with cooperative threads */
void cooperative_yield_thread_entry(void *p1, void *p2, void *p3) {
    struct thread_data *data = (struct thread_data *)p1;
    for (int i = 0; i < 5; i++) {
        data->executed_count++;
        k_yield();
    }
}

/* Test for timeslice with preemptible threads */
void preemptible_timeslice_thread_entry(void *p1, void *p2, void *p3) {
    struct thread_data *data = (struct thread_data *)p1;
    while (data->should_run) {
        data->executed_count++;
        k_busy_wait(1000); /* Simulate work */
    }
}

/* Test for k_thread_lock/unlock */
void lock_unlock_thread_entry(void *p1, void *p2, void *p3) {
    struct thread_data *data = (struct thread_data *)p1;
    k_thread_lock();
    data->executed_count++;
    k_busy_wait(10000); /* Simulate critical section */
    k_thread_unlock();
    data->executed_count++; /* Should run again after unlock */
}

/* Test for k_thread_suspend/resume */
void suspend_resume_thread_entry(void *p1, void *p2, void *p3) {
    struct thread_data *data = (struct thread_data *)p1;
    data->executed_count++; /* First run */
    k_thread_suspend(k_current_get()); /* Suspend itself */
    data->executed_count++; /* Second run after resume */
}


/* Test setup function */
static void setup_threads(void) {
    for (int i = 0; i < NUM_THREADS; i++) {
        test_tdata[i].id = i;
        test_tdata[i].executed_count = 0;
        test_tdata[i].should_run = true;
    }
}

/* Test case: threads_scheduling_test_sleep_cooperative */
ZTEST(schedule_api, test_sleep_cooperative) {
    setup_threads();

    for (int i = 0; i < NUM_THREADS; i++) {
        test_tdata[i].tid = k_thread_create(&test_tdata[i].thread, test_stacks[i], STACK_SIZE,
                                            cooperative_sleep_thread_entry, &test_tdata[i], NULL, NULL,
                                            K_PRIO_COOP(1), K_KERNEL, K_NO_WAIT); /* FIX: Added K_KERNEL */
        k_thread_name_set(test_tdata[i].tid, "coop_sleep_thread");
    }

    /* Give threads a chance to run and sleep. */
    /* Sleep for a duration that allows the cooperative thread to run once and then block. */
    /* The check happens before it can run again after waking up. */
    k_sleep(K_MSEC(150)); /* Longer than thread's sleep (100ms) but short enough for the test's expectation */

    for (int i = 0; i < NUM_THREADS; i++) {
        /* Expect the thread to run once, then sleep. */
        /* The assertion is checked after it has slept and potentially woken up, */
        /* but before it gets scheduled again to increment the counter. */
        zassert_equal(test_tdata[i].executed_count, 1,
                      "Cooperative sleep thread %d executed %d times, expected 1",
                      i, test_tdata[i].executed_count);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        k_thread_abort(test_tdata[i].tid);
    }
}

/* Test case: threads_scheduling_test_yield_cooperative */
ZTEST(schedule_api, test_yield_cooperative) {
    setup_threads();

    for (int i = 0; i < NUM_THREADS; i++) {
        test_tdata[i].tid = k_thread_create(&test_tdata[i].thread, test_stacks[i], STACK_SIZE,
                                            cooperative_yield_thread_entry, &test_tdata[i], NULL, NULL,
                                            K_PRIO_COOP(1), K_KERNEL, K_NO_WAIT); /* Added K_KERNEL */
        k_thread_name_set(test_tdata[i].tid, "coop_yield_thread");
    }

    /* Give threads a chance to run and yield multiple times */
    k_sleep(K_MSEC(100));

    for (int i = 0; i < NUM_THREADS; i++) {
        /* Each thread yields 5 times, so executed_count should be 5 */
        zassert_equal(test_tdata[i].executed_count, 5,
                      "Cooperative yield thread %d executed %d times, expected 5",
                      i, test_tdata[i].executed_count);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        k_thread_abort(test_tdata[i].tid);
    }
}

/* Test case: threads_scheduling_test_timeslice_preemptible */
ZTEST(schedule_api, test_timeslice_preemptible) {
    setup_threads();

    /* Set a timeslice for preemptible threads */
    k_thread_timeslice_set(K_MSEC(10), K_NO_WAIT);

    for (int i = 0; i < NUM_THREADS; i++) {
        test_tdata[i].tid = k_thread_create(&test_tdata[i].thread, test_stacks[i], STACK_SIZE,
                                               preemptible_timeslice_thread_entry, &test_tdata[i], NULL, NULL,
                                               K_PRIO_PREEMPT(1), K_KERNEL, K_NO_WAIT); /* Added K_KERNEL */
        k_thread_name_set(test_tdata[i].tid, "preempt_timeslice_thread");
    }

    /* Let threads run for a while */
    k_sleep(K_MSEC(100));

    for (int i = 0; i < NUM_THREADS; i++) {
        test_tdata[i].should_run = false; /* Stop threads */
    }

    /* Give time for threads to stop */
    k_sleep(K_MSEC(50));

    for (int i = 0; i < NUM_THREADS; i++) {
        /* Expect threads to have run multiple times due to timeslicing */
        zassert_true(test_tdata[i].executed_count > 5,
                     "Preemptible timeslice thread %d executed %d times, expected > 5",
                     i, test_tdata[i].executed_count);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        k_thread_abort(test_tdata[i].tid);
    }
}

/* Test case: threads_scheduling_test_lock_unlock */
ZTEST(schedule_api, test_lock_unlock) {
    setup_threads();

    for (int i = 0; i < NUM_THREADS; i++) {
        test_tdata[i].tid = k_thread_create(&test_tdata[i].thread, test_stacks[i], STACK_SIZE,
                                            lock_unlock_thread_entry, &test_tdata[i], NULL, NULL,
                                                                                        K_PRIO_COOP(1), K_KERNEL, K_NO_WAIT); /* Added K_KERNEL */
        k_thread_name_set(test_tdata[i].tid, "coop_lock_thread");
    }

    /* Give threads a chance to run and acquire/release lock */
    k_sleep(K_MSEC(200));

    for (int i = 0; i < NUM_THREADS; i++) {
        /* Each thread should have entered and exited the locked section once */
        zassert_equal(test_tdata[i].executed_count, 2,
                      "Cooperative lock thread %d executed %d times, expected 2",
                      i, test_tdata[i].executed_count);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        k_thread_abort(test_tdata[i].tid);
    }
}

/* Test case: threads_scheduling_test_suspend_resume */
ZTEST(schedule_api, test_suspend_resume) {
    setup_threads();

    test_tdata[0].tid = k_thread_create(&test_tdata[0].thread, test_stacks[0], STACK_SIZE,
                                        suspend_resume_thread_entry, &test_tdata[0], NULL, NULL,
                                        K_PRIO_COOP(1), K_KERNEL, K_NO_WAIT); /* Added K_KERNEL */
    k_thread_name_set(test_tdata[0].tid, "suspend_resume_thread");

    /* Give thread a chance to run once and suspend itself */
    k_sleep(K_MSEC(10));

    zassert_equal(test_tdata[0].executed_count, 1,
                  "Suspend/resume thread executed %d times, expected 1 before resume",
                  test_tdata[0].executed_count);

    k_thread_resume(test_tdata[0].tid);
    k_sleep(K_MSEC(10)); /* Give time to run again */

    zassert_equal(test_tdata[0].executed_count, 2,
                  "Suspend/resume thread executed %d times, expected 2 after resume",
                  test_tdata[0].executed_count);

    k_thread_abort(test_tdata[0].tid);
}


ZTEST_SUITE(schedule_api, NULL, NULL, NULL, NULL, NULL);
